    for insert to authenticated
    with check (
        bucket_id in ('patient_media', 'clinic_assets')
        and owner = auth.uid()
    );

drop policy if exists "dental_media_update" on storage.objects;
create policy "dental_media_update" on storage.objects
    for update to authenticated
    using (bucket_id in ('patient_media', 'clinic_assets') and owner = auth.uid())
    with check (bucket_id in ('patient_media', 'clinic_assets') and owner = auth.uid());

drop policy if exists "dental_media_delete" on storage.objects;
create policy "dental_media_delete" on storage.objects
    for delete to authenticated
    using (bucket_id in ('patient_media', 'clinic_assets') and owner = auth.uid());

-- ---------------------------------------------------------------------------
-- ۲) Policyهای باکت app_releases (فایل‌های انتشار نسخه)
-- ---------------------------------------------------------------------------
drop policy if exists "app_releases_read" on storage.objects;
create policy "app_releases_read" on storage.objects
    for select to public
    using (bucket_id = 'app_releases');

drop policy if exists "app_releases_insert" on storage.objects;
create policy "app_releases_insert" on storage.objects
    for insert to authenticated
    with check (bucket_id = 'app_releases' and owner = auth.uid());

-- ---------------------------------------------------------------------------
-- ۳) تابع حذف کامل حساب — cast صحیح uuid برای storage.objects.owner
-- ---------------------------------------------------------------------------
create or replace function public.delete_my_account()
returns void
language plpgsql
security definer
set search_path = public, auth, storage, extensions
as $$
declare
    p_uid text := auth.uid()::text;
    t text;
begin
    if p_uid is null then
        raise exception 'NOT_AUTHENTICATED';
    end if;

    foreach t in array array[
        'patients','treatments','payments','appointments','treatment_stages',
        'patient_documents','vendors','vendor_invoices','lab_orders',
        'equipment_maintenance','clinic_expenses','expense_payments',
        'personal_transactions','lab_services','installments',
        'treatment_templates','prescriptions','bank_accounts',
        'personal_sub_accounts','fixed_incomes','children_expenses',
        'clinic_settings','app_calendar_events','financial_ledger',
        'audit_events','drug_templates','staff_members',
        'unregistered_bank_sms','users'
    ]
    loop
        execute format('delete from public.%I where owner_id = %L', t, p_uid);
    end loop;

    -- فایل‌های Storage این کاربر (owner در storage.objects از نوع uuid است)
    delete from storage.objects
    where owner = p_uid::uuid and bucket_id in ('patient_media', 'clinic_assets');

    -- حذف خود حساب از auth.users (نشست‌ها هم باطل می‌شوند)
    perform auth.admin_delete_user(p_uid::uuid);
end;
$$;

revoke all on function public.delete_my_account() from public;
grant execute on function public.delete_my_account() to authenticated;


-- Source: 0007_api_settings.sql
-- ============================================================================
-- DentalPro — Migration 0007: نگهداری تنظیمات و کلیدهای API روی سرور (api_settings)
-- ============================================================================
-- طبق درخواست: «api ها در سرور ذخیره و فراخوانی بشن».
--
-- تا پیش از این، کلیدهای Gemini/Groq فقط روی خودِ گوشی (SecureSecretStore) ذخیره
-- می‌شدند؛ در نتیجه با تعویض دستگاه یا نصب مجدد، کاربر باید همه را دوباره وارد
-- می‌کرد و بین دستگاه‌ها هم هم‌سان نبودند. حالا هر کاربر یک ردیف در این جدول دارد
-- و اپ هنگام اجرا آن را از سرور می‌خواند و پس از هر ذخیره، روی سرور می‌نویسد.
--
-- امنیت:
--  * RLS فعال است و هر کاربر فقط ردیف خودش را می‌بیند (owner_id = auth.uid()).
--    هیچ کاربری کلید کاربر دیگر را نمی‌تواند بخواند — حتی با anon key.
--  * کلیدها به‌صورت متن ذخیره می‌شوند ولی فقط از پشت RLS و روی TLS قابل دسترسی‌اند.
--    نسخهٔ رمزنگاری‌شده روی دستگاه (SecureSecretStore) هم به‌عنوان کش آفلاین باقی
--    می‌ماند تا اپ بدون اینترنت هم کار کند.
--  * service_role هرگز داخل اپ نیست.
-- ============================================================================

-- ---------------------------------------------------------------------------
-- ۱) جدول
-- ---------------------------------------------------------------------------
create table if not exists public.api_settings (
    id                bigint generated always as identity primary key,
    sync_id           text    not null unique,            -- شناسهٔ یکتای ردیف (هم‌راستا با بقیهٔ جدول‌ها)
    owner_id          text    not null default '',        -- auth.uid() صاحب ردیف
    gemini_api_key    text    not null default '',        -- می‌تواند چند کلید جداشده با کاما باشد
    gemini_model      text    not null default '',
    groq_api_key      text    not null default '',
    active_provider   text    not null default 'gemini',  -- 'gemini' یا 'groq'
    updated_at        timestamptz not null default now(),
    created_at        timestamptz not null default now()
);

-- هر کاربر فقط یک ردیف تنظیمات دارد.
create unique index if not exists idx_api_settings_owner
    on public.api_settings (owner_id);

-- ---------------------------------------------------------------------------
-- ۲) امنیت سطری — فقط صاحب ردیف
-- ---------------------------------------------------------------------------
alter table public.api_settings enable row level security;

drop policy if exists "api_settings_owner_rows" on public.api_settings;
create policy "api_settings_owner_rows" on public.api_settings
    for all to authenticated
    using (owner_id = auth.uid()::text)
    with check (owner_id = auth.uid()::text);

-- ---------------------------------------------------------------------------
-- ۳) به‌روزرسانی خودکار updated_at
-- ---------------------------------------------------------------------------
create or replace function public.touch_api_settings_updated_at()
returns trigger
language plpgsql
as $$
begin
    new.updated_at = now();
    return new;
end;
$$;

drop trigger if exists trg_api_settings_touch on public.api_settings;
create trigger trg_api_settings_touch
    before update on public.api_settings
    for each row execute function public.touch_api_settings_updated_at();


-- Source: 0008_treatment_stage_sessions.sql
-- ============================================================================
-- DentalPro — Migration 0008: انتساب مراحل درمان به جلسه (stage_sessions)
-- ============================================================================
-- طبق درخواست: «با حذف جلسه وضعیت و مراحل تراپی‌ها همه جا آپدیت بشه».
--
-- تا پیش از این هیچ ردی از اینکه «کدام مرحله در کدام جلسه انجام شد» نگهداری
-- نمی‌شد؛ بنابراین با حذف یک جلسه معلوم نبود کدام مرحله باید برگردد و مراحلِ
-- انجام‌شده برای همیشه انجام‌شده می‌ماندند.
--
-- قالب مقدار: رکوردهای «appointmentId::stageName» که با «|||» از هم جدا شده‌اند.
-- مثال:  |||12::جلسه ۱: بی‌حسی…|||15::جلسه ۲: اُبچوریشن…
--
-- بدون این ستون، سینک ابری مقدار stageSessions را دور می‌ریخت (PostgREST ستون
-- ناشناخته را رد می‌کند) و انتساب‌ها بین دستگاه‌ها گم می‌شدند.
-- ============================================================================

alter table public.treatments
    add column if not exists stage_sessions text not null default '';

comment on column public.treatments.stage_sessions is
    'نگاشت مرحله به جلسه: رکوردهای appointmentId::stageName جداشده با |||';


-- Source: 0009_patient_issuance_place.sql
-- ============================================================================
-- DentalPro — Migration 0009: محل صدور شناسنامهٔ بیمار (issuance_place)
-- ============================================================================
-- طبق درخواست: کنار «کد ملی» یک فیلد «صادره از» اضافه شود که به‌صورت خودکار و
-- غیرقابل‌ویرایش از روی خودِ کد ملی پر می‌شود (مثل «خراسان جنوبی - بیرجند»).
--
-- مقدار از سه رقم اولِ کد ملی استخراج می‌شود؛ این سه رقم کدِ ادارهٔ ثبت احوالِ
-- صادرکننده است. نگاشت کامل (۵۹۱ کد) در سمت اپ داخل
-- app/src/main/java/com/example/util/NationalIdCityLookup.kt نگهداری می‌شود.
--
-- چرا ستون جدا و نه محاسبهٔ لحظه‌ای؟ چون جدول تقسیمات کشوری در طول زمان تغییر
-- می‌کند و مقدارِ ثبت‌شده در زمانِ پذیرش باید ثابت بماند؛ ضمناً گزارش‌ها و
-- جست‌وجوهای سمت سرور هم بدون تکرار منطق به آن دسترسی دارند.
--
-- بدون این ستون، سینک ابری مقدار issuancePlace را دور می‌ریخت (PostgREST ستون
-- ناشناخته را رد می‌کند) و «صادره از» بین دستگاه‌ها گم می‌شد.
-- ============================================================================

alter table public.patients
    add column if not exists issuance_place text not null default '';

comment on column public.patients.issuance_place is
    'محل صدور شناسنامه به شکل «استان - شهر»، مشتق‌شده از سه رقم اول کد ملی';


-- Source: 0010_cheque_transfer_links.sql
-- ============================================================================
-- DentalPro — Migration 0010: ردِ اسنادِ انتقال چک + تأییدهای بانکی
-- ============================================================================
-- تا پیش از این، وقتی یک چک به هزینه یا حساب شخصی «انتقال» داده می‌شد، اسنادِ
-- مقصد (expense_payments / personal_transactions / children_expenses) ساخته
-- می‌شدند اما هیچ ارجاعی از چک به آن‌ها نگهداری نمی‌شد.
--
-- نتیجه‌اش سه باگِ حسابداری بود:
--   ۱. حذف چک   → سندِ مقصد باقی می‌ماند و هزینه تا ابد «پرداخت‌شده» می‌ماند.
--   ۲. ویرایش مبلغ چک → مبلغِ سندِ مقصد قدیمی می‌ماند و دو طرف نامساوی می‌شدند.
--   ۳. برگشت‌خوردنِ چک → تسویهٔ هزینهٔ مقصد برنمی‌گشت.
--
-- ستون‌های transfer_*_id این ارجاع را نگه می‌دارند تا هر سه عملیات بتوانند
-- اثرِ انتقال را دقیقاً برگردانند.
--
-- دو ستون تأیید هم اضافه می‌شود؛ این‌ها «یک‌بارمصرف»‌اند: پس از true شدن دیگر
-- در رابط کاربری قابل برداشتن نیستند.
-- ============================================================================

alter table public.payments
    add column if not exists transfer_expense_payment_id  bigint,
    add column if not exists transfer_expense_id          bigint,
    add column if not exists transfer_transaction_id      bigint,
    add column if not exists transfer_children_expense_id bigint,
    add column if not exists bank_receipt_confirmed  boolean not null default false,
    add column if not exists bank_transfer_confirmed boolean not null default false;

comment on column public.payments.transfer_expense_payment_id is
    'ExpensePayment ساخته‌شده هنگام انتقال چک — برای برگرداندن اثر در حذف/ویرایش/برگشت';
comment on column public.payments.transfer_expense_id is
    'ClinicExpense ساخته‌شده هنگام انتقال چک (فقط وقتی هزینهٔ تازه ساخته شده باشد)';
comment on column public.payments.transfer_transaction_id is
    'PersonalTransaction ساخته‌شده هنگام انتقال چک به حساب شخصی/اشخاص';
comment on column public.payments.transfer_children_expense_id is
    'ChildrenExpense ساخته‌شده هنگام انتقال چک به «حساب اشخاص»';
comment on column public.payments.bank_receipt_confirmed is
    'تیک یک‌بارمصرف: دریافت بانکیِ چکِ پاس‌شده تأیید شد';
comment on column public.payments.bank_transfer_confirmed is
    'تیک یک‌بارمصرف: انتقال بانکیِ چکِ انتقال‌یافته تأیید شد';


-- Source: 0011_storage_categories.sql
-- ============================================================================
-- DentalPro — Migration 0011: دسته‌بندی فایل‌های Storage و جلوگیری از تکرار
-- ============================================================================
-- تا پیش از این هر آپلود مسیرِ «{uid}/{UUID}.jpg» می‌گرفت. دو ایراد داشت:
--
--   ۱. همهٔ فایل‌ها در یک پوشه ریخته می‌شدند — عکس چک، امضای بیمار، آواتار
--      پرسنل و لوگوی مطب همه کنار هم.
--   ۲. چون هر بار یک UUID تازه ساخته می‌شد، ذخیرهٔ دوبارهٔ *همان* فایل یک شیء
--      کاملاً جدید می‌ساخت. یک عکس واحد می‌توانست ده‌ها نسخه با شناسه‌های
--      متفاوت داشته باشد.
--
-- ساختار جدید:
--
--     {uid}/{category}/{sha256}.{ext}
--
--   • {uid}      → دسته‌بندی هر کاربر کاملاً جدا از کاربران دیگر
--   • {category} → cheques | patients | clinic | misc
--   • {sha256}   → هشِ محتوای فایل؛ محتوای یکسان همیشه همان مسیر را می‌دهد،
--                  پس آپلود دوم با x-upsert روی همان شیء می‌نویسد و نسخهٔ
--                  تکراری ساخته نمی‌شود.
--
-- سه پوشهٔ اصلی طبق درخواست:
--   cheques   → تصاویر چک
--   patients  → امضا و پروفایل و مدارک بیماران
--   clinic    → پروفایل پرسنل و پزشک، آواتار، و لوگوی مطب
-- ============================================================================

-- سیاست درج: علاوه بر owner، اولین بخشِ مسیر هم باید دقیقاً auth.uid() باشد.
-- این تضمین می‌کند فایل‌های هر کاربر فقط داخل پوشهٔ خودش بنشیند و هیچ کاربری
-- نتواند در پوشهٔ کاربر دیگر بنویسد.
drop policy if exists "dental_media_insert" on storage.objects;
create policy "dental_media_insert" on storage.objects
    for insert to authenticated
    with check (
        bucket_id in ('patient_media', 'clinic_assets')
        and owner = auth.uid()
        and (storage.foldername(name))[1] = auth.uid()::text
    );

-- سیاست به‌روزرسانی: x-upsert برای بازنویسیِ همان شیء به این نیاز دارد.
drop policy if exists "dental_media_update" on storage.objects;
create policy "dental_media_update" on storage.objects
    for update to authenticated
    using (
        bucket_id in ('patient_media', 'clinic_assets')
        and owner = auth.uid()
    )
    with check (
        bucket_id in ('patient_media', 'clinic_assets')
        and owner = auth.uid()
        and (storage.foldername(name))[1] = auth.uid()::text
    );

-- ---------------------------------------------------------------------------
-- گزارش فایل‌های تکراری (برای پاک‌سازی دستیِ داده‌های قدیمی)
-- ---------------------------------------------------------------------------
-- فایل‌هایی که پیش از این مهاجرت آپلود شده‌اند مسیر قدیمی دارند و ممکن است
-- چند نسخه از یک تصویر باشند. این view آن‌ها را بر اساس اندازه و مالک
-- گروه‌بندی می‌کند تا بشود بازبینی و حذفشان کرد. چیزی را خودکار حذف نمی‌کند.
create or replace view public.storage_duplicate_candidates as
select
    o.bucket_id,
    o.owner,
    (o.metadata ->> 'size')::bigint as size_bytes,
    count(*)                        as copies,
    array_agg(o.name order by o.created_at) as object_paths
from storage.objects o
where o.bucket_id in ('patient_media', 'clinic_assets')
  and o.metadata ? 'size'
group by o.bucket_id, o.owner, (o.metadata ->> 'size')::bigint
having count(*) > 1;

comment on view public.storage_duplicate_candidates is
    'نسخه‌های احتمالاً تکراری در Storage (هم‌مالک و هم‌اندازه) — برای بازبینی دستی. فایل‌های تازه به‌خاطر نام‌گذاری محتوامحور اصلاً تکراری نمی‌شوند.';


-- Source: 0012_bank_account_hide_order.sql
-- ============================================================================
-- DentalPro — Migration 0012: مخفی‌سازی و ترتیبِ کارت‌های بانکی
-- ============================================================================
-- برای «مخفی‌کردن کارت» و «جابه‌جایی کارت مثل کارت‌های واقعی» در صفحهٔ مدیریت
-- حساب‌ها (میانبر مکث طولانی روی لوگوی بانک)، دو ستون به جدول bank_accounts
-- اضافه می‌شود. بدون این ستون‌ها، سینکِ حساب بانکی با خطای PGRST204 («ستون
-- is_hidden یافت نشد») شکست می‌خورد، چون EntityMapper این فیلدها را هم به
-- PostgREST می‌فرستد.
-- ============================================================================

alter table public.bank_accounts
    add column if not exists is_hidden  boolean not null default false,
    add column if not exists sort_order integer not null default 0;

comment on column public.bank_accounts.is_hidden is
    'کارت در صفحهٔ مدیریت حساب‌ها مخفی است (میانبر مکث طولانی روی لوگو)';
comment on column public.bank_accounts.sort_order is
    'ترتیب نمایشِ کارت برای جابه‌جایی دستی (کوچک‌تر بالاتر)';


-- Source: 0013_expense_group_and_account_tree_level3.sql
-- ============================================================================
-- DentalPro — Migration 0013: هابِ «هزینه‌های مطب» + سطحِ سومِ درختِ حساب‌ها
-- ============================================================================
-- ۱) clinic_expenses.expense_group — گروهِ اصلیِ هزینه در هابِ چهارکارته:
--    LAB / CONSUMABLES / EQUIPMENT / RUNNING / OTHER (خالی = دسته‌بندی‌نشده).
-- ۲) personal_sub_accounts.grand_parent_name — سطحِ سومِ درخت (سرشاخهٔ ریشه)،
--    برای ساختارِ سه‌سطحیِ «سرشاخه ▸ شاخه ▸ حساب».
-- هم‌نگاشتِ camelCase↔snake_case سمتِ کلاینت: expenseGroup↔expense_group،
-- grandParentName↔grand_parent_name.
-- ============================================================================

alter table public.clinic_expenses
    add column if not exists expense_group text not null default '';

create index if not exists idx_clinic_expenses_group
    on public.clinic_expenses (owner_id, expense_group);

alter table public.personal_sub_accounts
    add column if not exists grand_parent_name text not null default '';

create index if not exists idx_personal_sub_accounts_grandparent
    on public.personal_sub_accounts (owner_id, grand_parent_name);


-- Source: 0014_party_accounts.sql
-- ============================================================================
-- DentalPro — Migration 0014: ظرف‌های حساب (Party Accounts) — طرف‌حساب‌های
-- چندظرفیِ هزینه‌های مطب
-- ============================================================================
-- مدل جدید:
--   • جدول party_accounts — هر «ظرف حساب» (مثل «لابراتوار آ»، «فنی مهندسی ب»،
--     «فروشگاه آ») یک ردیف مستقل با بخش (section)، عنوان (title)، نام (name) و
--     کد (code) است.
--   • clinic_expenses.party_account_id — هر فاکتور (بدهی ما) به ظرف وصل می‌شود.
--   • clinic_expenses.invoice_number — شمارهٔ فاکتورِ خودکارِ per-party.
--   • expense_payments.party_account_id — هر پرداختی به ظرف (یا فاکتورِ همان ظرف).
--   • payments.transfer_party_payment_id — ردِ پرداختیِ چکیِ ساخته‌شده هنگام
--     انتقال چک به ظرف (یک اشاره‌گر واحد به‌جای مسیرهای قبلی).
-- هم‌نگاشتِ camelCase↔snake_case سمتِ کلاینت:
--   partyAccountId↔party_account_id، partyAccountSyncId↔party_account_sync_id،
--   invoiceNumber↔invoice_number، transferPartyPaymentId↔transfer_party_payment_id،
--   invoiceSeq↔invoice_seq.
-- ============================================================================

create table if not exists public.party_accounts (
    section         text not null default '',
    code            text not null default '',
    title           text not null default '',
    name            text not null default '',
    phone           text not null default '',
    notes           text not null default '',
    invoice_seq     bigint not null default 0,
    owner_id        text not null default '',
    sync_id         text primary key,
    updated_at      bigint not null default 0,
    is_deleted      boolean not null default false
);

create index if not exists idx_party_accounts_owner_id on public.party_accounts (owner_id);
create index if not exists idx_party_accounts_section on public.party_accounts (owner_id, section);
create index if not exists idx_party_accounts_name on public.party_accounts (owner_id, name);

-- فاکتورها → ظرف
alter table public.clinic_expenses
    add column if not exists party_account_id bigint;
alter table public.clinic_expenses
    add column if not exists party_account_sync_id text not null default '';
alter table public.clinic_expenses
    add column if not exists invoice_number text not null default '';

create index if not exists idx_clinic_expenses_party_account
    on public.clinic_expenses (owner_id, party_account_id);

-- پرداختی‌ها → ظرف
alter table public.expense_payments
    add column if not exists party_account_id bigint;
alter table public.expense_payments
    add column if not exists party_account_sync_id text not null default '';

create index if not exists idx_expense_payments_party_account
    on public.expense_payments (owner_id, party_account_id);

-- ردِ پرداختیِ چکیِ انتقال‌یافته به ظرف
alter table public.payments
    add column if not exists transfer_party_payment_id bigint;

-- ---------------------------------------------------------------------------
-- RLS — همان Policy واحدِ «فقط مالک»
-- ---------------------------------------------------------------------------
alter table public.party_accounts enable row level security;

drop policy if exists "party_accounts_owner_rows" on public.party_accounts;
create policy "party_accounts_owner_rows" on public.party_accounts
    for all to authenticated
    using (owner_id = auth.uid()::text)
    with check (owner_id = auth.uid()::text);


-- Source: 0015_personal_subaccounts_opening_priority.sql
-- 0015 — حساب اشخاص: مبلغ اولیه (افتتاحیه) + شمارهٔ اولویت نمایش
